# ---------------- PPTX ----------------
prs=Presentation(); prs.slide_width=Inches(13.333); prs.slide_height=Inches(7.5)
blank=prs.slide_layouts[6]
def sep_slide(g):
    s=prs.slides.add_slide(blank)
    r,gr,b=int(g["color"][0:2],16),int(g["color"][2:4],16),int(g["color"][4:6],16)
    box=s.shapes.add_shape(1,0,0,prs.slide_width,prs.slide_height); box.fill.solid()
    box.fill.fore_color.rgb=RGBColor(r,gr,b); box.line.fill.background()
    tb=s.shapes.add_textbox(Inches(1),Inches(3),Inches(11.3),Inches(1.6)).text_frame
    tb.word_wrap=True
    p=tb.paragraphs[0]; p.text=f"GROUP {g['n']}"; p.font.size=Pt(28); p.font.bold=True
    p.font.color.rgb=RGBColor(255,255,255); p.alignment=PP_ALIGN.CENTER
    p2=tb.add_paragraph(); p2.text=g["title"]; p2.font.size=Pt(20); p2.font.color.rgb=RGBColor(255,255,255); p2.alignment=PP_ALIGN.CENTER
def img_slide(img,cap):
    s=prs.slides.add_slide(blank)
    path=os.path.join(ROOT,img)
    from PIL import Image
    w,h=Image.open(path).size; ar=w/h
    maxw,maxh=Inches(12.3),Inches(6.3)
    iw=maxw; ih=Emu(int(iw/ar))
    if ih>maxh: ih=maxh; iw=Emu(int(ih*ar))
    s.shapes.add_picture(path,int((prs.slide_width-iw)/2),Inches(0.5),iw,ih)
    tb=s.shapes.add_textbox(Inches(0.5),Inches(6.95),Inches(12.3),Inches(0.5)).text_frame
    tb.paragraphs[0].text=cap; tb.paragraphs[0].font.size=Pt(12); tb.paragraphs[0].alignment=PP_ALIGN.CENTER
def ph_slide(txt):
    s=prs.slides.add_slide(blank)
    box=s.shapes.add_shape(1,Inches(1.5),Inches(2.5),Inches(10.3),Inches(2.5))
    box.fill.solid(); box.fill.fore_color.rgb=RGBColor(245,245,245); box.line.color.rgb=RGBColor(180,180,180); box.line.dash_style=2
    tf=box.text_frame; tf.word_wrap=True
    p=tf.paragraphs[0]; p.text="◻ PLACEHOLDER"; p.font.size=Pt(16); p.font.bold=True; p.font.color.rgb=RGBColor(120,120,120); p.alignment=PP_ALIGN.CENTER
    p2=tf.add_paragraph(); p2.text=txt; p2.font.size=Pt(13); p2.font.color.rgb=RGBColor(90,90,90); p2.alignment=PP_ALIGN.CENTER

for g in GROUPS:
    sep_slide(g)
    for sl in g["slides"]:
        if "img" in sl and os.path.isfile(os.path.join(ROOT,sl["img"])): img_slide(sl["img"],sl["cap"])
        else: ph_slide(sl.get("ph") or sl.get("cap","(missing image)"))
prs.save(os.path.join(ROOT,"ablation_figures.pptx"))

# ---------------- HTML slideshow (batch-movie style) ----------------
slides=[]
for g in GROUPS:
    slides.append({"type":"sep","n":g["n"],"title":g["title"],"color":"#"+g["color"]})
    for sl in g["slides"]:
        if "img" in sl and os.path.isfile(os.path.join(ROOT,sl["img"])):
            slides.append({"type":"img","src":sl["img"],"cap":sl["cap"]})
        else:
            slides.append({"type":"ph","txt":sl.get("ph") or sl.get("cap","")})
html="""<!doctype html><html><head><meta charset=utf-8><title>Ablation figures</title>
<style>html,body{margin:0;height:100%;background:#111;font-family:Helvetica,Arial,sans-serif;overflow:hidden}
#stage{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
.slide{display:none;width:100%;height:100%;align-items:center;justify-content:center;flex-direction:column}
.slide.on{display:flex}
.slide img{max-width:94%;max-height:88%;background:#fff;box-shadow:0 4px 30px rgba(0,0,0,.5)}
.cap{color:#ddd;font-size:15px;margin-top:14px}
.sep{color:#fff;text-align:center}.sep .g{font-size:40px;font-weight:700;letter-spacing:3px}.sep .t{font-size:24px;margin-top:10px;opacity:.95}
#hud{position:fixed;bottom:10px;right:16px;color:#888;font-size:13px}
.ph{color:#aaa;border:2px dashed #555;border-radius:10px;padding:40px 60px;max-width:60%;text-align:center;font-size:16px}
</style></head><body><div id=stage>"""
for i,s in enumerate(slides):
    on="on" if i==0 else ""
    if s["type"]=="sep":
        html+=f'<div class="slide {on}" style="background:{s["color"]}"><div class=sep><div class=g>GROUP {s["n"]}</div><div class=t>{s["title"]}</div></div></div>'
    elif s["type"]=="img":
        html+=f'<div class="slide {on}"><img src="{s["src"]}"><div class=cap>{s["cap"]}</div></div>'
    else:
        html+=f'<div class="slide {on}"><div class=ph>◻ PLACEHOLDER<br><br>{s["txt"]}</div></div>'
html+="""</div><div id=hud></div><script>
let i=0,S=[...document.querySelectorAll('.slide')];
function show(n){S[i].classList.remove('on');i=(n+S.length)%S.length;S[i].classList.add('on');hud.textContent=(i+1)+' / '+S.length}
document.onkeydown=e=>{if(e.key==='ArrowRight'||e.key===' ')show(i+1);if(e.key==='ArrowLeft')show(i-1)};
document.onclick=e=>show(i+(e.clientX>innerWidth/2?1:-1));show(0);
</script></body></html>"""
open(os.path.join(ROOT,"index.html"),"w").write(html)
print(f"deck built: {len(slides)} HTML slides + pptx ({len(prs.slides.__iter__.__self__._sldIdLst)} pptx slides)")
print("index.html + ablation_figures.pptx")
